SELECT d.*, s.scene_name FROM device_info d
LEFT JOIN scene_info s ON d.scene_id = s.id
WHERE d.deleted = 0

    AND d.device_name LIKE CONCAT('%', #{keyword}, '%')


    AND d.device_type = #{deviceType}


    AND d.status = #{status}


    AND d.scene_id = #{sceneId}

ORDER BY d.created_at DESC

SELECT * FROM device_info WHERE status = 1 AND deleted = 0
AND scene_id = #{sceneId}
AND device_type = #{deviceType}

mapper.update:
UPDATE device_info
device_name = #{deviceName}, device_type = #{deviceType}, scene_id = #{sceneId}, ip_address = #{ipAddress}, model = #{modelSpec}, status = #{status}, updated_at = NOW()
WHERE id = #{id}
